import type { HelpTopic, HelpImage, Parameter } from "../topics";

const shot = (path: string, caption: string): HelpImage => ({ path: `reference/${path}.png`, caption });
const feather: Parameter = ["Adoucissement", "Adoucit la limite. 0 donne un bord net et c’est la valeur par défaut des nouveaux outils ; 1 utilise toute la zone d’adoucissement disponible. Un modificateur estompe son effet vers le champ inchangé ; un outil de peinture estompe sa propre contribution. Les objets existants conservent leur valeur enregistrée."];
const edge: Parameter = ["Bord : Fondre / Remplacer", "Fondre mélange le nouveau vecteur au vecteur existant à travers un bord progressif. Remplacer estompe plutôt le nouveau vecteur vers le calme. L’intérieur net utilise le nouveau vecteur dans les deux modes. Les cellules source non définies restent transparentes dans les deux modes."];
const size: Parameter = ["Taille et unités", "Diamètre du pinceau ou largeur du carré. px donne des proportions constantes à l’écran au moment de la création ; km / nm donne une distance au sol. Zoomer ensuite ne redimensionne pas les objets existants. L’unité choisie s’applique aussi aux autres réglages de taille de l’outil."];
const brushShape: Parameter = ["Forme du pinceau : Cercle / Carré", "Choisit le tampon balayé le long du geste. Cercle donne des extrémités arrondies ; Carré balaie des tampons carrés. Ce choix de géométrie est figé après le tracé ; l’animation de forme peut remodeler un objet existant."];
const speed: Parameter = ["Vitesse", "Intensité du vecteur dans l’unité de vitesse globale. Zéro peint des données de calme définies, ce qui diffère d’une zone vide."];
const direction: Parameter[] = [
  ["Mode de direction", "Constant utilise une seule direction au compas. Vers un point vise une cible séparément en chaque endroit ; À l’opposé d’un point inverse cette direction. Seules les options pertinentes sont affichées."],
  ["Direction", "Degrés dans la convention de / vers du projet. Le nord vaut 0°, l’est 90°, le sud 180°, l’ouest 270°. Avec un vent « de », 270° peint un vent qui se déplace vers l’est."],
  ["Cible / Choisir sur la carte", "Saisissez la longitude puis la latitude, ou appuyez sur Choisir sur la carte et cliquez sur la cible. Une longitude positive est à l’est ; une latitude positive est au nord. Ce clic de sélection place la cible au lieu de peindre."],
  ["Direction vers la cible : Orthodromie / Loxodromie", "Orthodromie utilise le relèvement local de la route sphérique la plus courte. Loxodromie utilise un cap constant jusqu’à la cible. Les deux peuvent différer sensiblement sur les longues routes et aux hautes latitudes."],
  ["Angle par rapport à la cible", "Décale la direction obtenue de −180° à +180°. Zéro vise directement vers la cible ou à l’opposé. Les angles positifs tournent dans le sens horaire ; les angles négatifs dans le sens antihoraire."],
];
const eyedropper: Parameter = ["Pipette", "Cliquez dessus, puis sur un point de la carte où des données sont définies, pour copier la vitesse et la direction dans l’outil. Elle échantillonne les données visibles du type de champ actif. Elle est disponible pour les modes à vecteur unique, et non pour les dégradés à deux extrémités."];
const modifier = "Un objet d’édition modifie les données situées sous lui dans son propre calque. Il ne peut pas créer d’écoulement sur des données non définies. Placez-le au-dessus des objets qu’il doit affecter. Sa transformation, sa quantité, sa durée de vie et ses propriétés prises en charge peuvent être animées.";

/** Référence hors ligne fournie avec l’application. Les valeurs des captures sont des exemples, pas des valeurs par défaut. */
const topics: HelpTopic[] = [
  { id: "workspace", group: "Espace de travail", title: "Premiers pas", paragraphs: [
    "VectorEffects crée des champs animés de vent et de courant de surface à partir d’objets peints, de fichiers GRIB, d’archives historiques et de macros capturées. Le canevas porte le fond de carte. Les calques vides sont transparents ; seules les données définies et les images superposées masquent ce qui se trouve dessous.",
    "Cette référence, dans laquelle vous pouvez rechercher, fonctionne hors ligne. Choisissez une page à gauche et cliquez sur les captures d’écran pour les voir en taille réelle. Les captures montrent des projets d’exemple d’une bêta antérieure : les valeurs d’adoucissement non nulles sont des exemples, l’angle du Cercle utilise désormais un curseur, et l’ancienne option Absolue de la Courbe s’appelle désormais Constant.",
  ], steps: ["Choisissez Nouveau et définissez une résolution de grille, le nombre d’heures par pas et le nombre de pas.", "Sélectionnez un calque non verrouillé, choisissez Pinceau, réglez la vitesse et la direction, puis faites glisser sur la carte.", "Sélectionnez le nouvel objet pour l’inspecter ou l’animer.", "Enregistrez au format .veproj pour conserver des objets modifiables. Utilisez Exporter en GRIB pour obtenir des données vectorielles utilisables dans un autre programme."],
    images: [shot("overview/overview", "La carte, les options d’outil, les calques, les propriétés, l’historique et la chronologie.")], related: ["projects", "tools", "layers", "animation", "export"] },
  { id: "projects", group: "Espace de travail", title: "Projets, enregistrement et récupération", paragraphs: ["Utilisez le menu Projet de la barre de titre pour Nouveau, Ouvrir, Enregistrer, Enregistrer sous et Fermer. Un projet contient sa grille, sa chronologie, ses calques, sa géométrie et son animation. Laissez les fichiers source importés à leurs chemins de référence lorsque vous rouvrez ou déplacez un projet. Après l’export, conservez le fichier .veproj comme original modifiable."],
    parameters: [["Nouveau : Nom", "Nomme le projet. Définissez le type de champ de chaque calque peint dans le panneau des calques."], ["Résolution", "Pas de la grille géographique. Une grille plus fine restitue de plus petits détails, mais allonge le temps d’évaluation et la taille de l’export."], ["Pas de temps / Pas", "Heures simulées entre deux pas et nombre total de pas. À ne pas confondre avec les images par seconde de la lecture."], ["Ouvrir / Récents", "Ouvre un fichier .veproj. La liste Récents de la page d’accueil montre les fichiers existants ; utilisez Ouvrir pour retrouver un projet déplacé."], ["Enregistrer / Enregistrer sous", "Enregistrer met à jour le fichier courant. Enregistrer sous choisit un nouveau chemin. Un projet jamais enregistré a d’abord besoin d’un chemin."], ["Fermer", "Ferme le projet. En cas de travail non enregistré, propose Enregistrer, Ne pas enregistrer ou Annuler."], ["Enregistrement automatique", "Les réglages permettent de conserver des instantanés de récupération, d’enregistrer directement dans le fichier du projet ou de laisser l’enregistrement manuel. Le déclenchement a lieu toutes les minutes ou toutes les cinquante modifications, selon ce qui arrive en premier. Une récupération est proposée après un plantage."], ["Annuler / Rétablir / Historique", "Annulent ou réappliquent les modifications du document ; l’Historique les décrit. Un geste terminé compte pour une seule modification : un seul Annuler supprime un trait ou rétablit une région effacée."]],
    images: [shot("overview/project_management", "Les commandes du projet et la roue dentée des Réglages.")], sections: [{ heading: "Projets régionaux", paragraphs: ["Un projet régional couvre une partie de la Terre au lieu de sa totalité. Son export ne contient que la grille de la région, si bien qu’une résolution fine reste légère. La région est choisie à la création du projet et ne pourra plus être modifiée. Ouvrir depuis GRIB ou Zarr crée de lui-même un projet régional lorsque le fichier ne couvre qu’une partie de la Terre."], parameters: [["Étendue : Global / Régional", "Global couvre la Terre entière. Régional affiche une petite carte, les quatre bords de la région et les préréglages, et l’estimation de l’export ne compte que la grille de la région."], ["Région sur la carte", "Faites glisser sur un espace vide pour tracer un cadre, à l’intérieur pour le déplacer, et avec Shift pour faire tourner la carte. Près de chaque bord, la carte tourne d’elle-même : un cadre peut ainsi traverser 180°. Le sens du glissement décide de quel côté le cadre fait le tour."], ["Nord / Sud / Ouest / Est", "Les bords en degrés, positifs au nord et à l’est. C’est d’eux que le projet est créé ; ils s’alignent vers l’extérieur sur la grille quand vous quittez un champ. Un cadre dont le bord est est inférieur au bord ouest s’étend vers l’est à travers 180°."], ["Tour complet / Arctique / Antarctique", "Tour complet couvre toutes les longitudes. Arctique et Antarctique remplissent une calotte de 60° au pôle et restent modifiables ensuite. Un tour complet d’un pôle à l’autre est la Terre entière : choisissez Global pour cela."], ["Utiliser la vue actuelle", "Dans la boîte de dialogue Nouveau projet, reprend la région de ce que montre la carte du projet ouvert."], ["Région dans la barre d’état", "Un projet régional affiche sa région à côté de la taille de la grille. En dehors, la carte est assombrie et ne contient aucune donnée."]] }],
    related: ["settings", "export", "troubleshooting"] },
  { id: "view", group: "Espace de travail", title: "Vue de la carte et conventions de direction", paragraphs: ["Déplacez la carte avec l’outil Main et zoomez avec la molette ou le pavé tactile. Les réglages de vue agissent sur la présentation, pas sur les vecteurs exportés."],
    parameters: [["Capture", "Passe en mode capture de macro pour enregistrer une région au fil des pas."], ["Mesurer", "Donne accès aux cercles de distance, au compas à pointes sèches, aux comparaisons de routes et à la vitesse de déplacement. Les mesures ne peignent aucune donnée vectorielle."], ["Glyphes", "Affiche ou masque les directions : barbules météorologiques pour le vent et flèches pour les courants."], ["Projection", "Recherchez parmi 270 vues par nom, pays ou code EPSG : cartes cylindriques et planisphères, globe orthographique, cartes azimutales, grilles polaires nord et sud, grilles nationales et toutes les zones UTM WGS84. Les cartes régionales s’ajustent à leur zone d’utilisation ; faire glisser un globe ou une carte azimutale déplace son centre. Une projection personnalisée accepte PROJ, WKT ou un code EPSG fourni. Les définitions fonctionnent hors ligne ; les grilles de correction de datum géodésique ne sont pas incluses. Ce réglage change la vue, pas les données enregistrées ni les exports. Dans les vues courbes, les tailles en pixels sont converties en géométrie au sol au point de départ du geste."], ["Graticule", "Affiche les lignes de référence de longitude et de latitude."], ["Échelle auto", "Ajuste chaque échelle de couleurs aux données visibles : les vitesses du vent et des courants, et les températures de surface de la mer. Désactivez-la pour comparer sur des échelles fixes."], ["Légende", "Affiche le dégradé, le type de champ, les unités de vitesse et les limites de l’échelle."], ["Relevé", "Affiche les coordonnées du pointeur, la vitesse et la direction échantillonnées, ainsi que le zoom. « aucun champ » signifie que les données ne sont pas définies."], ["Flèches et barbules de vent", "Une flèche pointe là où va le courant. Une barbule de vent pointe vers l’endroit d’où vient le vent, avec les barbes à cette extrémité. La barbule d’un vent de nord pointe vers le nord, mais l’écoulement se dirige vers le sud. La convention numérique de direction n’inverse pas les barbules météorologiques."]],
    images: [shot("overview/view_and_global_settings", "Les commandes de capture, de mesure, d’annulation et de rétablissement, et d’affichage de la carte.")], related: ["targets", "settings", "measure", "divergence"] },
  { id: "layers", group: "Espace de travail", title: "Calques, empilement et filtres de vitesse", paragraphs: ["La liste présente d’abord le haut de la pile. Les calques peints contiennent des objets et sont entièrement transparents là où ces objets ne définissent aucune donnée. Le fond de carte se trouve sous la pile et n’a pas de ligne de calque. Vous pouvez supprimer tous les calques ; ajoutez un nouveau calque pour reprendre la peinture ou utilisez Annuler pour en rétablir un."],
    parameters: [["+ / Importer / Calendrier / Antenne", "Ajoute une couche peinte ; importe un fichier GRIB2, un magasin Zarr de routage, une image ou des données SIG ; ou télécharge des données historiques. L’antenne récupère les derniers jours de données observées."], ["Nom / triangle d’ouverture", "Sélectionne le calque ou déplie sa liste d’objets."], ["Poignée de glissement / flèches haut et bas", "Réordonnez les calques en faisant glisser leur en-tête ou avec les flèches. Faites glisser les lignes d’objets pour les réordonner, ou sur un autre calque pour les y déplacer. Les objets d’édition et de duplication lisent ce qui se trouve sous eux dans ce calque."], ["Œil / cadenas", "Masque un calque ou empêche la modification de ses objets. Déverrouillez-le avant de dessiner ou de transformer."], ["Champ", "Choisit le type des calques peints. Les calques importés indiquent le type de leur source. Le vent et les courants restent des champs distincts."], ["Filtre de vitesse : minimum / maximum", "Active une plage de vitesses, bornes incluses, dans les unités d’affichage. Les valeurs hors de cette plage deviennent transparentes. Le filtre s’applique après les objets et les modifications du calque ; tous les types de calques le prennent en charge. Les seuils d’une image utilisent la vitesse du vecteur aux positions de l’image."], ["Dupliquer / ×", "Duplique un objet, supprime un objet, ou supprime un calque et ses objets. Annuler rétablit les suppressions dans le document."]],
    images: [shot("overview/layer_panel", "Les commandes des calques et le filtre de vitesse facultatif.")], related: ["selection", "imports", "history", "clone"] },
  { id: "selection", group: "Espace de travail", title: "Sélection, propriétés et transformations", paragraphs: ["Sélectionnez depuis le panneau des calques ou avec l’outil Sélectionner ; Maj-clic étend la sélection. Seuls les objets sélectionnés apparaissent dans l’aperçu en mouvement, même si d’autres objets chevauchent leurs limites. Choisir un calque ou tracer une région peut changer la portée de la sélection."],
    parameters: [["Position / Choisir", "Longitude et latitude de l’ancre. Choisir la définit d’un clic sur la carte. Faire glisser déplace l’ancre ; poser des clés sur Position la fait se déplacer."], ["Échelle", "Redimensionne autour de l’ancre. 100 % correspond à la taille d’origine. Change la géométrie, pas la vitesse des vecteurs."], ["Rotation", "Fait tourner l’objet et son champ autour de l’ancre. L’outil Faire pivoter le flux, lui, fait pivoter les vecteurs sans déplacer l’emprise du champ."], ["Visible", "Active l’objet ; posez des clés pour l’allumer et l’éteindre au fil du temps."], ["Poignées de transformation", "Déplacent, font tourner ou mettent à l’échelle la sélection au pas actuel, selon les règles des images clés."], ["Losanges de propriété", "Ajoutent une clé au pas sélectionné. La chronologie montre les mêmes propriétés et leurs clés."], ["Détails du calque", "Sans objet sélectionné, Propriétés décrit le calque actif : source, fichier ou archive, type de champ et pas couverts."], feather, edge],
    images: [shot("overview/properties_history", "Propriétés de l’objet, losanges d’animation et historique des modifications.")], related: ["animation", "shape", "tools"] },
  { id: "tools", group: "Outils de création", title: "Principes des outils : taille, adoucissement et bords", paragraphs: ["Les options d’outil règlent les nouveaux gestes ; les propriétés modifient les objets existants. Après avoir changé une option, le clic suivant sur la carte utilise l’outil. Choisir sur la carte et la pipette réservent volontairement un clic pour choisir ou échantillonner.", "Un geste terminé devient un objet ; des traits compatibles peuvent fusionner selon l’outil actif et les réglages. Les outils de création peignent des vecteurs, tandis que les outils d’édition modifient les données situées dessous. Seules les options utiles dans le mode courant sont affichées."],
    parameters: [size, brushShape, feather, edge, eyedropper, ["Géométrie en pixels", "px désigne des pixels au moment de la création, y compris aux hautes latitudes. La géographie enregistrée reste ancrée lorsque vous déplacez la carte, zoomez ou changez de projection."], ["Choix de géométrie figés", "Des choix comme la forme de tampon d’origine sont figés après la création. Utilisez l’animation de forme pour remodeler l’objet plutôt que de changer son mode de construction."]],
    images: [shot("overview/tool_bar", "Main, Sélectionner, Effacer, Insérer une macro, Pinceau, Cercle, Remplissage de forme, Tampon de duplication, Courbe, Masque, Intensifier / réduire, Diverger / converger, Faire pivoter le flux, Déformer et Déplacer.")], related: ["brush", "circle", "path", "eraser"] },
  { id: "brush", group: "Outils de création", title: "Pinceau", paragraphs: ["Faites glisser pour peindre un cercle ou un carré balayé ; cliquez pour un tampon unique. Utilisez un écoulement constant ou orientez chaque vecteur vers une cible ou à l’opposé. Le bord suit l’Adoucissement et le mode de Bord."],
    parameters: [brushShape, size, speed, ...direction, feather, edge, eyedropper],
    images: [shot("create_tools/brush_tool_constant", "Un pinceau avec une direction de vent constante. L’adoucissement est une valeur d’exemple.")], related: ["targets", "tools", "animation"] },
  { id: "targets", group: "Outils de création", title: "Relèvements vers une cible et décalages d’angle", paragraphs: ["Les modes à cible font varier la direction à travers un objet. Ils apparaissent sur le Pinceau et sur le Mode des vecteurs Constant du Remplissage de forme. Déplacer ou animer la cible change le point visé sans redessiner la forme."],
    parameters: direction,
    steps: ["Choisissez Vers un point ou À l’opposé d’un point.", "Saisissez les coordonnées ou utilisez Choisir sur la carte.", "Choisissez Orthodromie ou Loxodromie.", "Laissez Angle par rapport à la cible à 0 pour viser directement, ou saisissez un décalage.", "Peignez puis examinez plusieurs endroits avec le relevé ; les barbules de vent indiquent la direction « de »."],
    images: [shot("create_tools/brush_tool_point", "Coordonnées de la cible, choix de la route et décalage angulaire.")], related: ["view", "brush", "fill", "measure"] },
  { id: "circle", group: "Outils de création", title: "Tampon Cercle", paragraphs: ["Cliquez pour placer un écoulement circulaire autour du pointeur. Choisissez un disque, un anneau ou un disque avec un dégradé radial de vitesse. L’angle incline l’écoulement vers l’intérieur ou l’extérieur tout en conservant la vitesse choisie."],
    parameters: [["Remplissage : Plein / Périmètre / Plein avec dégradé", "Plein peint le disque à la Vitesse. Périmètre laisse son centre non défini. Plein avec dégradé fait varier la vitesse du centre vers le bord."], ["Diamètre / Largeur de l’anneau", "Diamètre extérieur et épaisseur de la bande du périmètre. Les deux utilisent l’unité px ou au sol choisie."], speed, ["Vitesse (centre) / Vitesse (bord)", "Vitesses aux extrémités pour Plein avec dégradé. Un centre à zéro est un calme défini, pas un trou vide."], ["Rotation : Horaire / Antihoraire", "Circulation dans le sens horaire ou antihoraire pour un angle à la tangente nul."], ["Angle par rapport à la tangente", "Curseur de −90° à +90°. −90° pointe directement vers l’intérieur ; 0° suit la tangente ; +90° pointe vers l’extérieur. Les valeurs intermédiaires donnent un écoulement en spirale. Le relevé est en degrés."], feather, edge],
    images: [shot("create_tools/circle_tool", "Paramètres du Cercle. L’angle par rapport à la tangente utilise désormais un curseur de −90° à +90°.")], related: ["tools", "divergence", "shape"] },
  { id: "fill", group: "Outils de création", title: "Remplissage de forme et dégradés de vecteurs", paragraphs: ["Peignez une forme prédéfinie tracée par glissement ou un polygone. Le contour détermine où les données existent ; le Mode des vecteurs détermine les vecteurs à l’intérieur. Un dégradé mélange les vecteurs des extrémités : des directions différentes aux extrémités peuvent donc aussi modifier la vitesse entre elles."],
    parameters: [["Forme : Polygone / Carré / Rectangle / Cercle", "Cliquez les sommets du polygone et terminez avec Entrée ou un double-clic. Tracez une forme prédéfinie par glissement. Échap annule une construction inachevée."], ["Forme en", "Les unités au sol définissent une géométrie géographique ; px utilise le plan d’écran cylindrique courant, ou une taille locale au sol dans les vues globe, azimutales et régionales."], ["Mode des vecteurs : Constant / Dégradé", "Constant utilise une seule vitesse et le mode de direction. Dégradé répartit des vecteurs de début et de fin à travers la forme."], speed, ...direction, ["Vitesse (début) / Vitesse (fin)", "Intensités aux deux extrémités opposées du dégradé."], ["Direction (début) / Direction (fin)", "Directions aux extrémités dans la convention de / vers du projet."], ["Axe du dégradé", "Relèvement géométrique du début du dégradé vers sa fin. C’est un axe, pas une direction « d’où vient le vent »."], feather, edge],
    images: [shot("create_tools/shape_fill", "Un polygone avec un dégradé de vecteurs.")], related: ["targets", "shape", "selection"] },
  { id: "clone", group: "Outils de création", title: "Tampon de duplication et transparence", paragraphs: ["Le tampon de duplication copie les vecteurs situés sous lui dans le même calque, pas le fond de carte ni les couleurs d’arrière-plan. Les trous de la source restent transparents pendant l’aperçu et après le relâchement. Une source réellement définie à vitesse nulle se copie toujours comme un calme.", "Les objets source sont évalués au pas actuel : leurs modifications et leur animation peuvent donc changer la duplication. Les objets situés au-dessus du tampon ne deviennent pas sa source."],
    parameters: [brushShape, size, ["Source / Choisir sur la carte", "Coordonnées de l’ancre source. Choisissez-les avant de peindre la destination."], ["Décalage : Aligné", "Conserve le décalage entre l’ancre de destination et la source. Quand le point d’échantillonnage se déplace, sa source se déplace d’autant."], ["Décalage : Fixe", "Reprend l’échantillonnage autour de la source choisie pour chaque tampon le long du trait, en appliquant cette zone source de façon répétée."], feather, edge],
    steps: ["Activez le calque qui contient les objets source.", "Choisissez Tampon de duplication et choisissez une source comportant des données définies.", "Réglez la taille, le mode de décalage et l’adoucissement.", "Peignez la destination. Les cellules source non définies la laissent inchangée."],
    images: [shot("create_tools/clone_stamp", "Les commandes Source et Décalage sur un champ dupliqué.")], related: ["layers", "tools", "troubleshooting"] },
  { id: "path", group: "Outils de création", title: "Outil Courbe", paragraphs: ["Peignez un couloir pour un courant-jet, un front ou un chenal. Placez les points de la route et terminez avec Entrée ou un double-clic. Échap abandonne un tracé inachevé. L’écoulement peut suivre la route ou rester constant."],
    parameters: [["Courbe : Polyligne / Bézier", "Polyligne relie les sommets par des segments droits. Bézier donne des segments courbes et des poignées de contrôle."], ["Largeur", "Largeur totale du couloir en px ou en unités au sol."], speed, ["Mode de direction : Constant", "Une seule direction au compas sur tout le couloir. Les versions antérieures l’appelaient Absolue ; le comportement est inchangé."], ["Mode de direction : Relatif au tracé", "Utilise la tangente locale. Une direction de 0° suit l’ordre des points, 180° revient en sens inverse et 90° coupe le tracé en travers."], ["Direction", "Un relèvement au compas en mode Constant, selon la convention du projet ; un décalage géométrique par rapport à la tangente en mode Relatif au tracé. Les décalages ne sont pas convertis en relèvements « d’où vient le vent »."], feather, edge, eyedropper],
    images: [shot("create_tools/path_tool", "Un couloir dont les vecteurs suivent la route.")], related: ["tools", "shape", "animation"] },
  { id: "mask", group: "Outils d’édition", title: "Masque", paragraphs: ["Un masque retire la couverture des données antérieures de son calque, laissant apparaître les calques inférieurs. Il reste un objet modifiable et animable. La gomme, elle, retire la géométrie de façon destructive."],
    parameters: [brushShape, size, feather, ["Inverser", "Désactivé, masque l’intérieur de l’emprise. Activé, masque l’extérieur, ce qui confine les données antérieures du calque à cette région."], edge],
    images: [shot("edit_tools/mask_tool", "Un masque traversant des formes peintes.")], related: ["eraser", "layers", "shape"] },
  { id: "intensity", group: "Outils d’édition", title: "Intensifier / réduire", paragraphs: [modifier, "Modifie la vitesse en conservant la direction. Un vecteur nul reste calme."],
    parameters: [size, ["Quantité", "Curseur de −100 % à +200 %. Zéro ne fait rien ; +100 % double la vitesse ; +200 % la triple ; −50 % la divise par deux ; −100 % donne un calme défini. L’adoucissement revient progressivement vers la vitesse d’origine au bord."], feather],
    images: [shot("edit_tools/intensify_tool", "Augmentation de la vitesse sous l’emprise d’un modificateur.")], related: ["divergence", "rotation", "layers"] },
  { id: "divergence", group: "Outils d’édition", title: "Diverger / converger", paragraphs: [modifier, "La divergence écarte l’écoulement du centre de l’emprise ou de l’axe du trait ; la convergence le rabat vers lui. La vitesse est conservée. Les barbules de vent pointent vers le vent entrant : leurs hampes peuvent pointer vers l’intérieur quand l’écoulement réel diverge.", "Pour un écoulement vers le nord à l’est du centre d’un tampon, la divergence ajoute une composante vers l’est ; la convergence ajoute une composante vers l’ouest."],
    parameters: [size, ["Quantité : Divergence (vers l’extérieur)", "Le côté gauche écarte l’écoulement vers l’extérieur. Une quantité plus grande ajoute une composante radiale plus forte avant de rétablir la vitesse d’origine."], ["Quantité : Convergence (vers l’intérieur)", "Le côté droit rabat l’écoulement vers l’intérieur. Le centre est neutre. Le pourcentage est une force d’effet, pas une variation de vitesse."], feather],
    images: [shot("edit_tools/convergence_divergence_tool", "Divergence sur des données de vent ; les barbules indiquent la direction « de ».")], related: ["view", "circle", "rotation"] },
  { id: "rotation", group: "Outils d’édition", title: "Faire pivoter le flux", paragraphs: [modifier, "Fait pivoter les vecteurs sur place tout en laissant leur emprise et leurs structures spatiales là où elles étaient."],
    parameters: [size, ["Sens de rotation : Horaire / Antihoraire", "Sens de rotation de l’écoulement sous-jacent."], ["Quantité", "De 0° à 180°. Zéro est neutre, 90° tourne l’écoulement de côté et 180° inverse sa direction. La vitesse est conservée."], feather],
    images: [shot("edit_tools/rotation_tool", "Rotation des vecteurs sous-jacents de 30°.")], related: ["selection", "warp", "intensity"] },
  { id: "warp", group: "Outils d’édition", title: "Déformer et déplacer", paragraphs: [modifier, "Déformer déplace les positions d’échantillonnage pour pousser ou tordre les structures du champ. Déplacer est un outil en deux temps : peignez une zone pour la sélectionner, relâchez, puis faites glisser la sélection à sa nouvelle position. Avec un Adoucissement à zéro, le champ sélectionné se déplace intact ; l’Adoucissement adoucit son bord intérieur tout en préservant le cœur. Les deux limites restent en surbrillance, reliées par une ligne entre leurs centres. La zone libérée et une bande autour de la destination sont interpolées pour se raccorder au champ environnant. Échap annule la sélection en attente."],
    parameters: [size, ["Déformer : Poussée", "Décale le champ vers Pousser vers. Maj-glisser définit la traction de l’ancre vers sa destination."], ["Pousser vers", "Coordonnées de destination communes à tous les pas. Pousser vers ne peut pas recevoir de clé ; Position peut toujours animer l’emplacement de l’objet."], ["Déformer : Torsion", "Tord l’échantillonnage autour de l’ancre."], ["Torsion", "Angle signé de −360° à +360°. Zéro est neutre ; le signe change le sens de rotation."], ["Déplacer : Distance d’interpolation", "Jusqu’où l’interpolation s’étend hors de la limite de destination, dans l’unité px ou de distance géographique du pinceau. À zéro, la zone source libérée est tout de même comblée."], ["Animation du déplacement", "La Position de la sélection, la Position du déplacement (relative), l’Adoucissement et la Distance d’interpolation ont des pistes indépendantes. La Position du déplacement a des coordonnées couplées qui partagent clés et accélération. Maj-glisser la sélection source pose une clé sur sa destination relative avec Clé automatique. Déplacer n’a pas d’animation de forme."], feather],
    images: [shot("edit_tools/warp_tool", "Mode Tordre avec la taille, l’angle et l’adoucissement.")], related: ["rotation", "selection", "shape"] },
  { id: "eraser", group: "Outils d’édition", title: "Gomme et découpes destructives", paragraphs: ["La gomme retire la géométrie des objets ou des données du calque actif. Elle ne peint ni arrière-plan ni valeurs de vitesse nulle. Annuler rétablit la découpe ; utilisez un masque pour obtenir un objet de découpe distinct et amovible.", "Les découpes restent retirées quand les périmètres animés changent. Choisir l’outil Effacer quitte l’édition de forme et masque les points du périmètre."],
    parameters: [brushShape, size, feather], steps: ["Activez et déverrouillez le calque voulu.", "Choisissez Cercle ou Carré et une taille en px ou au sol.", "Utilisez un Adoucissement de 0 pour une découpe nette, ou augmentez-le pour plus de douceur.", "Faites glisser sur la région indésirable. Annuler la rétablit."],
    images: [shot("utility_tools/eraser", "Une gomme de 400 pixels en projection de Mercator.")], related: ["mask", "shape", "layers"] },
  { id: "animation", group: "Animation", title: "Images clés et mouvement", paragraphs: ["La tête de lecture choisit le pas en cours de modification. Dépliez un objet pour voir ses propriétés animables. Les losanges sont des clés ; entre elles, les valeurs suivent leur interpolation. Placez-vous sur un pas, ajoutez un losange, puis modifiez les propriétés ou les poignées sur la carte.", "Clé automatique peut créer des clés pendant l’édition. Les modes de direction, le Remplissage du Cercle, le Décalage du tampon de duplication, Inverser du Masque ainsi que le mode et Pousser vers de Déformer s’appliquent à tout l’objet et ne peuvent pas recevoir de clé. Dès qu’une propriété a des clés, une modification à un autre pas ajoute une clé au lieu de changer toute l’animation."],
    parameters: [["Lecture / pause / Arrêter", "Lecture avance à partir du pas actuel ; Pause le fige ; Arrêter revient au début."], ["Boucle", "Reprend la lecture après le dernier pas."], ["pas/s", "Images affichées par seconde demandées, indépendantes des heures simulées par pas. Les données importées non préparées peuvent demander un temps de chargement."], ["Clé automatique", "Contrôle la création automatique de clés lors de la modification des propriétés animables."], ["Pas", "Nombre total de pas. Raccourcir la chronologie peut supprimer des clés ultérieures et demande une confirmation."], ["Temps / Ajouter l’heure de début / ×", "Définit ou supprime l’heure de début UTC. Sans elle, la règle affiche des heures relatives ; avec elle, les dates UTC absolues sont disponibles."], ["Bande de disponibilité", "Montre les pas préparés. Les grands jeux de données importés demandent du temps pour la préparation initiale."], ["Graphique des valeurs / Interpolation", "Affichez le graphique d’une propriété pour examiner ses valeurs dans le temps. Cliquez avec le bouton droit sur une clé pour choisir l’interpolation du segment qui en part."], ["Sélection de clés", "Cliquez sur des clés pour les sélectionner, faites-les glisser pour les déplacer et appuyez sur Suppr pour les supprimer. Les clés sélectionnées ont priorité sur la suppression d’objets."]],
    images: [shot("overview/timeline", "Transport, cadence, clé automatique, heure et barres de durée de vie."), shot("timeline/keyframes", "Clés de propriété et points des pas intermédiaires.")],
    sections: [{ heading: "Se déplacer à vitesse constante", paragraphs: ["Cliquez sur →+ sur Position. Le mouvement commence au pas sélectionné et se termine à la clé de position suivante, ou au dernier pas de l’objet s’il n’y a pas de clé ultérieure."], parameters: [["Direction vers (° vrais)", "Direction du déplacement : 0° nord, 90° est, 180° sud, 270° ouest. Toujours « vers », quel que soit l’affichage du vent en « de »."], ["Vitesse", "Vitesse de déplacement dans l’unité de vitesse globale."], ["Ajouter le mouvement / Annuler", "Crée la trajectoire de l’intervalle indiqué ou annule. Les clés existantes dans l’intervalle demandent une confirmation avant d’être remplacées. Un seul Annuler rétablit la piste précédente."]], images: [shot("timeline/position_constant_motion", "La commande →+ sur Position."), shot("timeline/position_constant_motion_dialog", "Direction et vitesse de déplacement pour l’intervalle indiqué.")] }],
    related: ["spans", "shape", "links", "motion-vectors"] },
  { id: "spans", group: "Animation", title: "Durée de vie d’un objet : pas de début et de fin", paragraphs: ["La barre de durée de vie fixe les pas, bornes incluses, pendant lesquels un objet contribue. Elle est indépendante des clés d’animation : un objet peut avoir une longue piste de mouvement mais n’être actif que sur une partie de celle-ci."],
    parameters: [["Poignée de début", "Faites glisser la prise gauche pour fixer le premier pas actif. Sa zone cliquable dépasse la fine barre dessinée."], ["Poignée de fin", "Faites glisser la prise droite pour fixer le dernier pas actif."], ["Corps de la barre", "Faites-le glisser pour déplacer tout l’intervalle en conservant sa longueur. Un clic sans mouvement sélectionne l’objet."], ["Aperçu au relâchement", "La barre garde la position de relâchement pendant que les lignes du document se rafraîchissent, sans revenir brusquement à l’ancienne plage."]],
    images: [shot("timeline/keyframes", "La barre de durée de vie se trouve au-dessus des pistes de propriétés.")], related: ["animation", "macros", "shape"] },
  { id: "shape", group: "Animation", title: "Animer la forme d’un objet", paragraphs: ["L’animation de forme est un mode d’édition pour les objets de création et d’édition, à l’exception des macros capturées, des patchs et des sélections de Déplacer. Les points du périmètre conservent leur identité d’une clé à l’autre et n’apparaissent que lorsque le bouton de forme de l’objet est activé."],
    steps: ["Sélectionnez l’objet et cliquez sur l’icône de périmètre à côté de son nom dans la chronologie.", "Au pas voulu, faites glisser les points et ajoutez si nécessaire une clé Forme avec son losange.", "Allez à un autre pas et déplacez de nouveau les points.", "Parcourez la chronologie pour examiner le contour qui change.", "Cliquez de nouveau sur l’icône de périmètre ou choisissez un autre outil pour quitter le mode et masquer les points."],
    parameters: [["Points du périmètre", "Positions le long du contour au pas actuel. Ils font partie de l’animation de l’objet et ne sont pas des objets distincts."], ["Piste Forme / losange", "Enregistre un contour à un pas. D’autres clés définissent les contours entre lesquels interpoler."], ["Interaction avec la gomme", "Les découpes restent destructives et ne sont pas rétablies du seul fait que le contour change plus tard."]],
    images: [shot("timeline/shape_keyframes", "Les points du périmètre et une piste Forme avec des clés.")], related: ["animation", "eraser", "selection"] },
  { id: "links", group: "Animation", title: "Lier la position ou la rotation", paragraphs: ["Un lien de suivi fait suivre à une propriété la propriété correspondante d’un objet principal, pour que des structures se déplacent ou tournent ensemble."],
    steps: ["Dépliez les deux objets.", "Cliquez sur la commande de lien Position ou Rotation de l’objet suiveur.", "Cliquez sur la ligne de cette propriété de l’objet principal. Cliquer de nouveau sur la commande armée annule.", "Modifiez la piste de l’objet principal. Cliquez sur le lien actif pour délier avant de créer une piste indépendante."],
    parameters: [["Commande de lien", "Arme, signale ou supprime un lien de suivi. Le glissement entre lignes correspondantes est aussi pris en charge."], ["Losanges suivis", "Représentent l’animation de l’objet principal. Modifiez-les sur la ligne de l’objet principal au lieu de les traiter comme des clés indépendantes du suiveur."]],
    images: [shot("timeline/link_motion_to_object", "Une ligne Position suivie, avec l’info-bulle pour délier.")], related: ["animation", "motion-vectors"] },
  { id: "motion-vectors", group: "Animation", title: "Ajouter le mouvement de l’objet à ses vecteurs", paragraphs: ["Déplacer une forme et changer ses vecteurs peints sont deux choix distincts. La contribution du mouvement ajoute le déplacement de l’objet au champ. Elle ne crée pas de trajectoire : animez d’abord les transformations, puis activez leurs contributions.", "Les vecteurs de mouvement se combinent aux vecteurs d’origine : la vitesse comme la direction peuvent donc changer."],
    parameters: [["Contribution du mouvement (⇢)", "Ajoute le mouvement associé à cette transformation. Position apporte la vitesse de déplacement ; les contributions d’Échelle et de Rotation, lorsqu’elles sont disponibles, tiennent compte de l’évolution de ces transformations."], ["Mouvement constant (→+)", "Crée une trajectoire de Position. Ce n’est pas la même chose qu’ajouter le mouvement aux vecteurs peints."], ["Transformation statique", "Une transformation qui ne change pas n’apporte aucun mouvement, même avec la commande activée."]],
    images: [shot("timeline/add_motion_vectors", "Contribution du mouvement activée sur une piste Position avec des clés.")], related: ["animation", "links", "macros"] },
  { id: "imports", group: "Données et macros", title: "GRIB, Zarr et images de référence", paragraphs: ["Les imports GRIB et Zarr de routage ajoutent les champs de vent et de courant pris en charge sous forme de calques distincts. Chaque pas utilise l’heure de la source attribuée à ce pas du projet. Les images sont des références visuelles et ne contiennent aucune donnée vectorielle exportable."],
    parameters: [["Importer", "Un seul bouton pour tout fichier dont une couche peut venir. Le dialogue ne montre que ce qu’il lit : GRIB2 (.grib2, .grb2, .grib, .grb), un magasin Zarr de routage, des images (.tif, .tiff, .png, .jpg, .jpeg) et des données SIG (.geojson, .json, .shp, .kml, .kmz, .gpx). Un GeoTIFF devient une couche image."], ["Fichier GRIB2", "Choisissez le fichier ; examinez son champ, ses pas, son chemin et sa couverture dans les Détails du calque. Gardez-le disponible pour rouvrir le projet."], ["Magasin Zarr / Ouvrir depuis Zarr", "Avec Importer, choisissez le fichier zarr.json à la racine du magasin de routage ; c’est son dossier qui est importé. Le vent et les courants deviennent des couches ordinaires modifiables. Ouvrir depuis Zarr sur l’écran d’accueil choisit le dossier lui-même et reprend aussi la grille et l’horloge du projet depuis le magasin, dans la limite de 240 pas. Gardez le dossier d’origine disponible pour rouvrir le projet."], ["Cellules des pas importés", "Sélectionnez des pas dans la ligne de chronologie du calque source. Copier, coller et supprimer agissent sur ces pas au lieu des clés d’objets. Maj étend une série."], ["Image", "Choisissez une image de référence et son emplacement géographique."], ["Taille et forme de l’image", "Sélectionnez le calque d’image et utilisez l’outil Main. Faites glisser un coin pour redimensionner proportionnellement, ou une poignée latérale pour étirer la largeur ou la hauteur. Le coin ou le côté opposé reste fixe. Faites glisser à l’intérieur de l’image pour la déplacer. Annuler défait tout le glissement."], ["Opacité de l’image", "Règle à quel point l’image recouvre le canevas."], ["Filtre de vitesse", "Restreint la couverture du champ à une plage acceptée ; les filtres d’image utilisent la vitesse aux emplacements de l’image."], ["Fichier manquant", "Rétablissez son chemin de référence ou importez-le de nouveau. Les données manquantes ne sont pas traitées comme un calme réel."], ["Calque désaligné", "Sur une chronologie dotée d’une heure de début, un calque de fichier dont le premier champ n’est pas à l’heure du pas où il tombe est mis en évidence dans la chronologie, avec le décalage dans son info-bulle. Rien n’est bloqué et l’export n’est pas affecté. Le bouton près du nom déplace les champs vers les pas dont ils portent l’heure ; les pas masqués, collés et gommés les suivent. Une annulation rétablit tout."]], related: ["history", "layers", "export"] },
  { id: "history", group: "Données et macros", title: "Télécharger des vents et courants historiques", paragraphs: ["Le calendrier du panneau des calques ouvre l’import historique. Choisissez des dates UTC et des archives ; chacune devient un calque. Les téléchargements en cache peuvent être réutilisés lorsque vous revenez sur une demande ou la relancez."],
    parameters: [["Début (UTC) / Fin (UTC)", "Bornes incluses, à l’heure pleine. Des intervalles plus longs impliquent plus de pas et de téléchargements ; consultez le résumé de la charge de travail."], ["Fixer le début de la chronologie", "Aligne le début du projet sur la première heure UTC demandée."], ["Vent ERA5", "Sélectionne l’archive de vent à 10 m proposée."], ["GlobCurrent", "Sélectionne l’archive de courant de surface total proposée."], ["Importer / Annuler", "Lance la demande sélectionnée, ou laisse le projet inchangé avant le lancement."], ["Progression", "Le panneau inférieur rend compte du téléchargement et de la préparation. Les deux archives ou des plages plus longues augmentent le travail."], ["Relancer le téléchargement", "Apparaît à côté d’un échec dans le panneau inférieur et répète la demande enregistrée en réutilisant les données en cache. Parcourir la carte ne le fait pas disparaître."]],
    images: [shot("layers/import_history", "Dates UTC, choix des archives, alignement et résumé de la charge de travail.")], related: ["imports", "nrt", "animation", "capture", "troubleshooting"] },
  { id: "nrt", group: "Données et macros", title: "Télécharger des vents et courants en temps quasi réel", paragraphs: ["Le bouton à l’antenne, à côté du calendrier du panneau des calques, télécharge les derniers jours de données observées, jusqu’à maintenant, pour les produits que vous cochez, et ajoute un calque pour chacun. Ce qui est téléchargé est écrit sur le disque, de sorte que le projet s’ouvre ensuite hors ligne. Le réseau n’est sollicité que lorsque vous appuyez sur Importer.", "Les produits ont environ un jour de retard sur le présent ; les pas les plus récents sont donc généralement vides. Un produit quotidien, comme DUACS, est affiché à chaque pas de sa journée. Un produit qui ne peut pas être téléchargé est nommé dans la barre d’état, et les autres arrivent tout de même. Les calques se comportent comme des calques GRIB importés : le filtre de vitesse, la gomme et l’export s’y appliquent. Les calques de température de surface de la mer font exception : ils sont dessinés sous le champ et lus sous le pointeur, et ne sont jamais filtrés, gommés ni exportés."],
    parameters: [["Jours", "Le nombre de jours avant aujourd’hui (UTC) où commence la période, à 00:00 ; elle se termine toujours maintenant. Le plus grand nombre proposé est celui que peut contenir une chronologie de 240 pas au pas du projet."], ["Fixer / Déplacer le début de la chronologie", "Attribue au premier pas du projet le début de la période, pour que les dates de la chronologie correspondent aux données. Le libellé indique Déplacer lorsque le projet a déjà une heure de début."], ["Allonger la chronologie", "Proposé lorsque la période exige plus de pas que le projet n’en compte. Ajoute des pas pour que la chronologie atteigne le présent ; elle n’est jamais raccourcie. Si la case n’est pas cochée, seules les heures que les pas existants peuvent afficher sont téléchargées."], ["Copernicus MULTIOBS", "Courant de surface total — géostrophique, dû au vent et de marée — horaire, à 0,25°."], ["Copernicus DUACS", "Courant de surface géostrophique issu de l’altimétrie satellitaire, quotidien ; affiché à chaque pas de sa journée."], ["Vent L4 Copernicus", "Vent à 10 m combinant satellites et modèle, horaire."], ["ASCAT Metop-B/C", "Vent à 10 m par diffusiomètre des deux satellites Metop, un calque par jour avec les passages de la journée fusionnés ; aucune valeur là où aucun satellite n’est passé."], ["CCMP NRT", "Vent à 10 m CCMP (Cross-Calibrated Multi-Platform), version 2.1 en temps quasi réel, toutes les 6 heures à 0,25°, de Remote Sensing Systems, lu sur le serveur OceanWatch de la NOAA. Il couvre de 78° S à 78° N ; rien n’est affiché plus près des pôles."], ["NOAA Blended Seawinds", "La combinaison par la NOAA du vent à 10 m de tous les diffusiomètres et radiomètres en orbite, toutes les six heures à 0,25°, depuis NOAA CoastWatch. Chaque jour est un fichier contenant ses quatre heures, téléchargé une seule fois."], ["NOAA OISST", "Température de surface de la mer par interpolation optimale de la NOAA, version 2.1 : quotidienne à 0,25°, issue des satellites, des navires et des bouées, distribuée par NOAA NCEI. Ajoute un calque de température de surface de la mer."], ["NOAA Geo-Polar Blended", "Fusion par la NOAA de la température de surface de la mer mesurée par satellites géostationnaires et à orbite polaire, quotidienne, lue à 0,25° depuis NOAA CoastWatch. Ajoute un calque de température de surface de la mer."], ["OSTIA (Met Office)", "Analyse opérationnelle de la température de surface de la mer et des glaces (OSTIA) du Met Office, quotidienne, lue à 0,2° depuis le Copernicus Marine Service. Ajoute un calque de température de surface de la mer."], ["CMC", "L’analyse quotidienne de température de surface de la mer du Centre météorologique canadien, lue à 0,25° depuis sa grille de 0,1°, depuis l’archive PO.DAAC de la NASA. Ajoute une couche de température de surface de la mer. Nécessite un jeton NASA Earthdata, défini dans les Réglages ; sans lui, elle est grisée."], ["Jeton NASA Earthdata", "Se définit dans Réglages → NASA Earthdata. Il est conservé dans un fichier à part, envoyé uniquement à l’archive PO.DAAC de la NASA lors du téléchargement de CMC, et n’est jamais réaffiché ni transmis à un client d’IA."], ["Calque de température de surface de la mer", "Dessiné sous le champ en couleur, de −2 °C à 32 °C, avec sa propre légende et la température sous le pointeur dans le relevé. Affichage seulement : on ne peint jamais dessus et il n’est jamais exporté. L’unité se règle dans les Réglages."], ["Coût", "Le nombre de téléchargements et la taille approximative sur le disque, affichés avant l’import."]], related: ["history", "imports", "animation"] },
  { id: "capture", group: "Données et macros", title: "Enregistrer et prévisualiser une macro", paragraphs: ["La capture enregistre les données vectorielles d’une région au fil des pas, éventuellement avec son déplacement. Elle utilise le type de champ actif ; les couleurs du fond de carte et les images ne sont pas des données vectorielles."],
    steps: ["Choisissez le champ source et le premier pas.", "Passez en mode capture, choisissez une forme et tracez la région.", "Activez Enregistrer le mouvement si nécessaire, puis Démarrer la capture.", "Allez aux pas suivants et déplacez la région pour suivre la structure.", "Terminez l’enregistrement pour prévisualiser la plage de pas.", "Utilisez Modifier la macro pour la retoucher, Enregistrer la macro pour la nommer et la conserver, ou Annuler pour l’abandonner."],
    parameters: [["Forme", "Contour de la région qui délimite les données capturées."], ["Enregistrer le mouvement", "Conserve le déplacement de la région de capture sur les pas visités."], ["Clés d’enregistrement", "Positions de la région aux pas visités. Parcourez la chronologie pour examiner le trajet entre elles."], ["Aperçu", "Lit les données capturées isolément. Cliquez sur la carte pour prévisualiser leur placement ailleurs."], ["Modifier la macro / Enregistrer la macro / Annuler", "Retouche, enregistre dans la bibliothèque ou abandonne la capture. Les autres modifications du document sont désactivées pendant l’enregistrement ou l’aperçu."]],
    images: [shot("creating_macros/create_macro_select_frame_and_area", "Choisir le premier pas et la région."), shot("creating_macros/record_macro_end", "Déplacer la région à un pas ultérieur."), shot("creating_macros/record_macro_preview", "Aperçu avant l’enregistrement.")], related: ["macros", "animation", "history"] },
  { id: "macros", group: "Données et macros", title: "Insérer des macros et interpoler les pas manquants", paragraphs: ["Choisissez Insérer une macro, sélectionnez une entrée de la bibliothèque et cliquez pour la placer au pas actuel. Le contour au survol prévisualise le placement dans le calque peint sélectionné uniquement. Un curseur barré signifie que la macro n’a pas de données correspondant au type vent/courant de ce calque, ou que le calque ne peut pas l’accepter ; aucun objet n’est placé dans un autre calque. Une macro contenant les deux champs utilise celui qui correspond au calque sélectionné. Elle devient un objet dont les transformations et la durée de vie sont modifiables.", "La stratégie d’interpolation apparaît quand les pas enregistrés sont plus espacés que les pas du projet, par exemple une macro tri-horaire dans un projet horaire. Cette stratégie s’applique à toute la macro et ne peut pas être animée."],
    parameters: [["Sélecteur de macro / Actualiser", "Sélectionnez une entrée de la bibliothèque par nom, durée, nombre de pas et indicateur de mouvement. Actualiser recharge le contenu de la bibliothèque."], ["Répéter les images", "Par défaut : maintient le dernier pas enregistré jusqu’au suivant."], ["Images vides", "N’affiche aucune donnée de macro sur les pas intermédiaires, laissant voir ce qui se trouve dessous."], ["Interpoler", "Mélange u et v séparément et interpole le mouvement enregistré. L’interpolation par composantes évite qu’une direction fasse un tour complet au passage d’un relèvement de 360° à 0°."], ["Boucle", "Répète la séquence enregistrée pendant la durée de vie active de l’objet."], feather, edge, ["Répertoire de la bibliothèque", "Se configure dans les Réglages. Les projets conservent leurs propres pas de macro insérés : supprimer la bibliothèque ne retire pas les macros déjà présentes dans un projet."]],
    images: [shot("creating_macros/insert_macro_hover", "Le contour d’insertion suit le pointeur."), shot("creating_macros/insert_macro_clicked", "Une macro insérée et sa barre de durée de vie.")], related: ["capture", "spans", "motion-vectors", "settings"] },
  { id: "measure", group: "Mesures", title: "Comparaison orthodromie et loxodromie", paragraphs: ["Choisissez Orthodromie / loxodromie sous Mesurer et cliquez deux extrémités. L’orthodromie est la route sphérique la plus courte, dont le relèvement local varie. Une loxodromie garde un cap constant et est généralement plus longue."],
    parameters: [["Étiquette GC", "Distance et relèvement initial de la route orthodromique."], ["Étiquette RL", "Distance et cap constant de la loxodromie."], ["Extrémités", "Faites-les glisser pour réviser la comparaison."], ["Alt-clic sur un point", "Supprime cette mesure."], ["Effacer orthodromie / loxodromie", "Supprime toutes les comparaisons de routes et conserve les autres mesures."], ["Tout effacer", "Supprime toutes les annotations de mesure, pas les objets vectoriels."]],
    images: [shot("global_utility_tools/great_circle_rhumb_line", "Courbe orthodromique et loxodromie en pointillés entre les mêmes extrémités.")], related: ["targets", "rings", "dividers"] },
  { id: "rings", group: "Mesures", title: "Cercles de distance", paragraphs: ["Choisissez Cercles de distance et cliquez un centre. Les cercles représentent des distances au sol : une projection peut donc déformer leur aspect."],
    parameters: [["Intervalle", "Distance au sol entre deux cercles dans l’unité de distance globale."], ["Cercles", "Nombre de cercles. Le rayon extérieur vaut Intervalle × Cercles."], ["Modifier le dernier ensemble", "Les changements mettent à jour l’ensemble actif. Cliquez ailleurs pour ajouter un ensemble ; faites glisser une poignée de centre pour le déplacer."], ["Alt-clic sur un point", "Supprime cet ensemble de cercles."], ["Effacer les cercles de distance / Tout effacer", "Efface les ensembles de cercles ou tous les types de mesure."]],
    images: [shot("global_utility_tools/range_rings", "Vingt cercles espacés de 50 nm, pour un rayon extérieur de 1000 nm.")], related: ["measure", "dividers", "settings"] },
  { id: "dividers", group: "Mesures", title: "Compas à pointes sèches et distances en plusieurs branches", paragraphs: ["Choisissez Compas à pointes sèches et cliquez des points de route successifs. Chaque branche affiche sa distance et son relèvement ; la chaîne donne la distance cumulée. Les mesures ne modifient pas les vecteurs exportés."],
    parameters: [["Clic", "Ajoute une branche depuis le dernier point de route."], ["Entrée / Échap", "Termine la chaîne en cours."], ["Poignées des points de route", "Faites-les glisser pour réviser la route et recalculer les distances."], ["Alt-clic sur un point", "Supprime cette mesure."], ["Effacer le compas / Tout effacer", "Efface les chaînes ou toutes les annotations de mesure."]],
    images: [shot("global_utility_tools/dividers", "Une chaîne en plusieurs branches avec relèvements et distances totales.")], related: ["measure", "rings"] },
  { id: "feature-speed", group: "Mesures", title: "Vitesse et direction d’un système en mouvement", paragraphs: ["Choisissez Vitesse de déplacement dans Mesurer pour savoir à quelle vitesse et dans quelle direction se déplace une dépression, un front ou un tourbillon. Cliquez sur le système, amenez la chronologie à un pas de temps ultérieur, puis cliquez de nouveau dessus. La ligne entre les deux marques porte la vitesse moyenne dans l’unité de vitesse globale et le cap suivi par le système ; la distance et le temps écoulé sont inscrits près de la seconde marque.", "Entre les deux clics, la chronologie ne fait qu’avancer : les pas antérieurs sont estompés, et le parcours de la règle, les touches de pas et la lecture s’arrêtent au pas de la première marque. La direction est un cap — là où se dirige le système — quelle que soit la convention de direction que le projet utilise pour le vent. Les mesures ne modifient pas les vecteurs exportés."],
    parameters: [["Premier clic", "Marque la position du système au pas de temps courant et empêche la chronologie de revenir en arrière."], ["Second clic", "À un pas de temps ultérieur, marque l’endroit où le système s’est déplacé et termine la mesure."], ["Échap / Annuler", "Abandonne la première marque et libère la chronologie."], ["Étiquettes", "Vitesse moyenne et cap le long de la ligne ; distance et heures écoulées près de la seconde marque."], ["Poignées des marques", "Faites glisser l’une ou l’autre marque pour réviser la mesure. Les pas de temps restent ceux des clics."], ["Alt-clic sur un point", "Supprime cette mesure."], ["Effacer les vitesses de déplacement / Tout effacer", "Efface ces mesures ou toutes les annotations de mesure."]], related: ["dividers", "measure", "animation"] },
  { id: "settings", group: "Réglages et export", title: "Thèmes, unités, flèches et barbules de vent", paragraphs: ["Ouvrez les Réglages avec la roue dentée ou le bouton Réglages de la page d’accueil. La section Apparence propose Original (Minuit), Sauge et sarcelle, Océan, Prune, Braise, Papier et Personnalisé. Les thèmes s’appliquent immédiatement à toute l’application et sont conservés indépendamment des projets. Les unités et les styles de glyphes sont des préférences de l’application ; les échelles de couleurs et les dégradés sont enregistrés dans le projet. Les choix de présentation ne modifient pas les intensités ni les directions exportées."],
    parameters: [["Distance : km / nm", "Convertit la saisie et les relevés entre kilomètres et milles marins."], ["Vitesse : kt / mph / km/h", "Convertit les valeurs des outils, les relevés, les légendes et les boîtes de dialogue de mouvement. Les valeurs sont converties, pas réinterprétées."], ["Température : °C / °F", "Convertit la température de surface de la mer de la légende et du relevé. Le calque contient des °C ; seul l’affichage change."], ["Flèches / Barbules de vent", "Réglages de style et aperçus distincts pour chaque type de glyphe."], ["Taille (%)", "Longueur du glyphe en pourcentage de sa taille normale à l’écran, de 25 % à 300 %."], ["Densité (%)", "Nombre et espacement des glyphes. Une densité plus élevée montre plus de directions locales mais peut encombrer la carte."], ["Épaisseur du trait", "Épaisseur de la hampe et des barbes."], ["Couleur / Opacité (%)", "Couleur du glyphe et transparence globale."], ["Estomper selon la vitesse", "Réduit l’opacité dans les écoulements plus lents tout en gardant visible un vent calme défini."], ["Ombre portée", "Ajoute du contraste derrière les glyphes."], ["Couleur / opacité de l’ombre", "Couleur et transparence propres à l’ombre."], ["Ombre X / Y (px)", "Décalage horizontal et vertical de l’ombre en pixels."], ["Réinitialiser les flèches / Réinitialiser les barbules", "Rétablit l’apparence par défaut de ce style."], ["Échelles de couleurs du projet", "Vitesses maximales fixes du vent et du courant lorsque l’Échelle auto est désactivée."], ["Dégradés du projet", "Palettes de couleurs distinctes pour le vent et le courant, choisies parmi des échantillons."], ["Valeurs par défaut des nouveaux projets", "Limites initiales des échelles de vent et de courant pour les projets créés ensuite."], ["Raccourcis", "Cliquez sur un raccourci, puis appuyez sur la combinaison de remplacement. Les raccourcis affichés décrivent votre configuration actuelle."], ["Enregistrement automatique / Macros", "Choisissez la récupération, l’enregistrement direct ou l’enregistrement manuel. Définissez le répertoire des macros ou supprimez des entrées de la bibliothèque. La suppression dans la bibliothèque demande une confirmation et conserve les macros déjà insérées dans les projets."], ["Service MCP", "Permet à un client d’IA de cet ordinateur de piloter l’application via le Model Context Protocol. Désactivé par défaut ; une fois activé, la section affiche l’adresse locale et le jeton. Ajouter à Claude Code et Ajouter à Codex inscrivent le service dans la configuration propre de ce client ; après un changement de jeton ou de port, le même bouton la met à jour. Ajouter à Claude Desktop ouvre une extension VectorEffects dans le programme d’installation de Claude Desktop, où vous la confirmez ; elle s’installe une fois et suit d’elle-même un nouveau jeton ou un nouveau port. Configuration pour d’autres clients contient la même chose sous forme de texte à copier. Renouveler le jeton révoque l’ancien. La barre d’état affiche MCP et le dernier outil utilisé tant qu’un client est connecté. Ce qu’un client d’IA peut faire sans demander se choisit au-dessus des boutons Ajouter : par défaut, tout ce qui reste dans VectorEffects et peut être annulé s’exécute sans demande, tandis qu’enregistrer, exporter, télécharger et abandonner des modifications demandent toujours. Le choix s’applique quand un bouton Ajouter est pressé."]],
    images: [{ path: "settings.png", caption: "Réglages d’apparence distincts pour les flèches et les barbules de vent." }], related: ["view", "projects", "macros"] },
  { id: "export", group: "Réglages et export", title: "Exporter en GRIB2", paragraphs: ["Exporter en GRIB écrit les vecteurs évalués pour d’autres applications. La boîte de dialogue demande la destination et l’heure de référence de la prévision. Les sélecteurs de centre producteur et de précision ont été supprimés. Chaque message porte la mention « Created with VectorEffects ».", "L’export utilise la grille du projet, indépendamment du zoom, de la taille de l’écran et de la densité des glyphes. Conservez le fichier .veproj pour continuer à modifier le projet."],
    parameters: [["Destination", "Chemin du fichier .grib2 de sortie."], ["Début de la prévision (UTC)", "Heure de référence de la prévision. Les décalages des pas y sont ajoutés pour obtenir les heures de validité des messages ; vérifiez-les par rapport à la période historique ou de prévision voulue."], ["Taille estimée", "Une limite supérieure. Les champs clairsemés ou constants peuvent être beaucoup plus petits."], ["Choisir l’emplacement et exporter / progression / Annuler l’export", "Lance l’export et en suit l’avancement, ou l’arrête sans modifier le projet."], ["Données non définies", "Les cellules non couvertes utilisent les bitmaps GRIB. Elles ne sont pas écrites comme des zéros. Un calme peint délibérément reste un zéro défini."], ["Vent et courant", "u et v sont écrits séparément pour chaque pas et chaque type de champ visible. Les calques masqués ne contribuent pas."], ["Mention", "Chaque message contient « Created with VectorEffects » dans sa section d’usage local. Un lecteur peut ne pas l’afficher parmi les commandes de prévision ordinaires."], ["Compression automatique", "Compression simple standard sur 16 bits, avec des champs constants compacts. Aucun choix de précision n’est nécessaire."], ["Contenu de la vue exclu", "Le fond de carte, les images, les glyphes, les poignées de sélection et les mesures ne deviennent pas des vecteurs."], ["Exporter en Zarr", "Écrit plutôt les mêmes vecteurs évalués dans un répertoire Zarr V3, selon la disposition de routage : un seul tableau de données Float16 de u10, v10, ucur et vcur, avec les coordonnées time, param, latitude et longitude, la latitude partant de 90° et la longitude de -180°. Les blocs couvrent trois jours sur 10 degrés, compressés en Zstd et regroupés en fragments par bassin océanique ; les cellules non couvertes valent NaN, et une région sans aucune donnée n’est pas écrite du tout."]],
    images: [{ path: "export.png", caption: "La boîte de dialogue d’export simplifiée, avec l’heure de référence UTC et le choix de la destination." }],
    related: ["projects", "layers", "imports", "troubleshooting"] },
  { id: "troubleshooting", group: "Réglages et export", title: "Dépannage", paragraphs: ["Vérifiez d’abord le calque actif, le pas sélectionné et le type de champ. Annuler aide à isoler une modification récente. Enregistrez une copie avant d’examiner un projet complexe."],
    parameters: [["Rien n’apparaît", "Vérifiez la visibilité, le verrouillage, la durée de vie de l’objet et les filtres de vitesse. Les outils d’édition ont besoin de données définies en dessous. Une Quantité neutre ou une sélection de Déplacer sans déplacement ne fait rien."], ["Premier clic après un réglage", "L’appui ordinaire suivant valide la saisie numérique et utilise l’outil. Choisir sur la carte, la capture et la pipette réservent le clic à leur action indiquée."], ["Duplication vide", "Les vecteurs source doivent se trouver sous le tampon de duplication, dans le même calque. Une source vide reste transparente ; un calme défini se copie toujours."], ["La divergence semble inversée", "Les barbules pointent vers le vent entrant. La divergence écarte l’écoulement réel vers l’extérieur ; la convergence le rabat vers l’intérieur."], ["L’objet n’est plus dans le projet", "Annuler ou une suppression peut retirer la sélection. Les sélections périmées et les réponses obsolètes des propriétés sont désormais ignorées. Si une vraie modification échoue encore, sélectionnez de nouveau la ligne actuelle de l’objet."], ["Lecture lente des données importées", "Attendez la bande de disponibilité. Les premières lectures d’archive et l’évaluation peuvent retarder la cadence en pas/s demandée."], ["Échec du téléchargement historique", "Utilisez Relancer le téléchargement à côté de l’erreur. Vérifiez la période demandée et la connexion si l’archive reste indisponible."], ["Source ou projet récent manquant", "Rétablissez le chemin de référence, ou utilisez Ouvrir / Importer pour le retrouver. Les chemins de projets manquants sont retirés de la liste des projets récents."], ["Expiration de la bêta", "Cette bêta expire le 1er janvier 2027, selon la date du système. Installez une version à jour pour continuer."]],
    related: ["layers", "clone", "divergence", "history", "export"] },
];

export default topics;
